pygments.lexers.__init__.find_lexer_clas:
def find_lexer_class_for_filename(_fn, code=None):
    """Get a lexer for a filename.

    If multiple lexers match the filename pattern, use ``analyse_text()`` to
    figure out which one is more appropriate.

    Returns None if not found.
    """
    matches = []
    fn = basename(_fn)
    for (modname, name, _, filenames, _) in LEXERS.values():
        for filename in filenames:
            if _fn_matches(fn, filename):
                if name not in _lexer_cache:
                    _load_lexers(modname)
                matches.append((_lexer_cache[name], filename))
    for cls in find_plugin_lexers():
        for filename in cls.filenames:
            if _fn_matches(fn, filename):
                matches.append((cls, filename))
    if isinstance(code, bytes):
        code = guess_decode(code)

    def get_rating(info):
        (cls, filename) = info
        bonus = (('*' not in filename and 0.5) or 0)
        if code:
            return (cls.analyse_text(code) + bonus, cls.__name__)
        return (cls.priority + bonus, cls.__name__)
    if matches:
        matches.sort(key=get_rating)
        return matches[-1][0]

pygments.cmdline._print_help:
def _print_help(what, name):
    try:
        if what == 'lexer':
            cls = get_lexer_by_name(name)
            print(f'Help on the {cls.name} lexer:')
            print(dedent(cls.__doc__))
        elif what == 'formatter':
            cls = find_formatter_class(name)
            print(f'Help on the {cls.name} formatter:')
            print(dedent(cls.__doc__))
        elif what == 'filter':
            cls = find_filter_class(name)
            print(f'Help on the {name} filter:')
            print(dedent(cls.__doc__))
        return 0
    except (AttributeError, ValueError):
        print(f'{what} not found!', file=sys.stderr)
        return 1

pygments.lexers.__init__.load_lexer_from:
def load_lexer_from_file(filename, lexername='CustomLexer', **options):
    """Load a lexer from a file.

    This method expects a file located relative to the current working
    directory, which contains a Lexer class. By default, it expects the
    Lexer to be name CustomLexer; you can specify your own class name
    as the second argument to this function.

    Users should be very careful with the input, because this method
    is equivalent to running eval on the input file.

    Raises ClassNotFound if there are any problems importing the Lexer.

    .. versionadded:: 2.2
    """
    try:
        custom_namespace = {}
        with open(filename, 'rb') as f:
            exec(f.read(), custom_namespace)
        if lexername not in custom_namespace:
            raise ClassNotFound(f'no valid {lexername} class found in {filename}')
        lexer_class = custom_namespace[lexername]
        return lexer_class(**options)
    except OSError as err:
        raise ClassNotFound(f'cannot read {filename}: {err}')
    except ClassNotFound:
        raise
    except Exception as err:
        raise ClassNotFound(f'error when loading custom lexer: {err}')

pygments.lexers._sourcemod_builtins.get_:
def get_sm_functions():
    f = opener.open('http://docs.sourcemod.net/api/SMfuncs.js')
    r = re.compile('SMfunctions\\[\\d+\\] = Array \\("(?:public )?([^,]+)",".+"\\);')
    functions = []
    for line in f:
        m = r.match(line.decode())
        if m is not None:
            functions.append(m.groups()[0])
    return functions

pygments.formatters.html.webify:
def webify(color):
    if (color.startswith('calc') or color.startswith('var')):
        return color
    else:
        color = color.upper()
        if (len(color) == 6 and (color[0] == color[1] and color[2] == color[3] and color[4] == color[5])):
            return f'#{color[0]}{color[2]}{color[4]}'
        else:
            return f'#{color}'

pygments.filters.__init__.get_filter_by_:
def get_filter_by_name(filtername, **options):
    """Return an instantiated filter.

    Options are passed to the filter initializer if wanted.
    Raise a ClassNotFound if not found.
    """
    cls = find_filter_class(filtername)
    if cls:
        return cls(**options)
    else:
        raise ClassNotFound(f'filter {filtername!r} not found')
